use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_special_char(c: char) -> bool {
    c == ' ' || c == ',' || c == '.'
}

spec fn replace_with_colon_spec(input: Seq<char>) -> Seq<char> {
    Seq::new(input.len(), |i: int| 
        if is_special_char(input[i]) {
            ':'
        } else {
            input[i]
        }
    )
}

fn replace_with_colon(str1: &Vec<char>) -> (result: Vec<char>)
    requires
        str1@.len() < 0xffff_ffff,  // Reasonable bound for vector length
    ensures
        result@ == replace_with_colon_spec(str1@),
        result@.len() == str1@.len(),
        forall|i: int| 0 <= i < str1@.len() ==> 
            (is_special_char(str1@[i]) ==> result@[i] == ':') &&
            (!is_special_char(str1@[i]) ==> result@[i] == str1@[i])
{
    let mut result_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < str1.len()
        invariant
            0 <= idx <= str1@.len(),
            result_vec@.len() == idx,
            forall|i: int| 0 <= i < idx ==> 
                (is_special_char(str1@[i]) ==> result_vec@[i] == ':') &&
                (!is_special_char(str1@[i]) ==> result_vec@[i] == str1@[i]),
        decreases str1@.len() - idx,
    {
        let current_char = str1[idx];
        let new_char = if is_special_char(current_char) {
            ':'
        } else {
            current_char
        };
        
        result_vec.push(new_char);
        idx = idx + 1;
    }
    
    result_vec
}

}
